<script>
function hjmSend(text) {
  try {
    if (window.parent && typeof window.parent.triggerSlash === 'function') {
      window.parent.triggerSlash('/send ' + text + '|/trigger');
      return;
    }
  } catch(e) {}
  try {
    const ta = window.parent.document.querySelector('#send_textarea');
    if (ta) {
      const cur = ta.value;
      ta.value = cur && cur.trim() !== '' ? (cur.includes(text) ? cur : cur + '\n' + text) : text;
      ta.dispatchEvent(new Event('input', { bubbles: true }));
      ta.focus();
      return;
    }
  } catch(e) {}
  try {
    window.parent.postMessage({ type: 'sendChat', text: text }, '*');
  } catch(e) {}
}

function hjmCp(el) {
  const s = el.querySelector('.hjm-txt');
  if (!s) return;
  hjmSend(s.innerText);
  if (!el.querySelector('.hjm-cap')) {
    const c2 = document.createElement('div');
    c2.className = 'hjm-cap';
    c2.innerText = '✨已选择';
    el.appendChild(c2);
    setTimeout(() => c2.remove(), 800);
  }
}

(function(){
  const r = document.getElementById('hjm-raw-mini');
  const c = document.getElementById('hjm-opt-ctn-mini');
  if (!r || !c) return;
  const rawData = r.value || r.textContent || '';
  const ls = rawData.trim().split(/\r?\n/).filter(e => e.trim() !== '');
  ls.forEach(l => {
    const m = l.trim().match(/^([A-Z])\.\s*(.*)/i);
    if (m) {
      const d = document.createElement('div');
      d.className = 'hjm-c-btn';
      d.setAttribute('onclick', 'hjmCp(this)');
      let txt = m[2]
        .replace(/<q[^>]*>/gi, '"')
        .replace(/<\/q>/gi, '"')
        .replace(/<em[^>]*>/gi, '（')
        .replace(/<\/em>/gi, '）')
        .replace(/&quot;/gi, '"')
        .replace(/<[^>]+>/g, '');
      d.innerHTML = '<span class="hjm-arrow">➤</span><b>' + m[1].toUpperCase() + '.</b><span class="hjm-txt"></span>';
      d.querySelector('.hjm-txt').textContent = txt;
      c.appendChild(d);
    }
  });
  updateIframeHeight();
})();

function updateIframeHeight() {
  const h = document.documentElement.scrollHeight || document.body.scrollHeight;
  if (window.parent && window.parent !== window) {
    try { window.parent.postMessage({ type: 'resizeIframe', height: h }, '*'); } catch(e) {}
  }
}
window.addEventListener('load', updateIframeHeight);
window.addEventListener('resize', updateIframeHeight);
</script>

