      /* ================= OP 与标题待机画面 ================= */
      body.prelude-active {
        overflow: hidden;
      }

      .lk-prelude {
        position: fixed;
        inset: 0;
        z-index: 2147483000;
        width: 100%;
        height: 100%;
        max-width: 100%;
        max-height: 100%;
        overflow: hidden;
        color: #fff;
        background: #000;
        container-type: size;
        opacity: 1;
        visibility: visible;
        transition:
          opacity 420ms ease,
          visibility 420ms ease;
      }

      /* SillyTavern 直接挂载时，只占用当前消息块，不覆盖整个酒馆界面。 */
      .lk-prelude-host-active {
        position: relative !important;
        width: 100% !important;
        height: auto !important;
        min-width: 0 !important;
        min-height: 0 !important;
        aspect-ratio: 16 / 9;
        overflow: hidden !important;
        isolation: isolate;
      }

      .lk-prelude.is-message-embedded {
        position: absolute;
        width: 100%;
        height: 100%;
        min-height: 0;
      }

      .lk-prelude.is-finished {
        opacity: 0;
        visibility: hidden;
        pointer-events: none;
      }

      .lk-prelude-screen {
        position: absolute;
        inset: 0;
        display: grid;
        place-items: center;
        container-type: size;
        overflow: hidden;
        visibility: hidden;
        opacity: 0;
        pointer-events: none;
        transition:
          opacity 420ms ease,
          visibility 420ms ease;
      }

      /* 前景舞台承载视频/图片/Logo/提示，所有组件以同一 16:9 基准整体缩放。 */
      .lk-prelude-stage {
        position: relative;
        z-index: 2;
        width: 100%;
        height: auto;
        max-width: 100%;
        max-height: 100%;
        aspect-ratio: 16 / 9;
        overflow: hidden;
        isolation: isolate;
        container-type: size;
        background: #050403;
        box-shadow: 0 0 52px rgba(0, 0, 0, 0.5);
      }

      @supports (width: 1cqw) {
        .lk-prelude-stage {
          width: min(100cqw, calc(100cqh * 1.7777778));
          height: min(100cqh, calc(100cqw * 0.5625));
        }
      }

      .lk-prelude-screen.is-active {
        visibility: visible;
        opacity: 1;
        pointer-events: auto;
      }

      .lk-opening-screen {
        isolation: isolate;
        cursor: pointer;
        background: #100b09;
      }

      .lk-opening-video-backdrop {
        position: absolute;
        inset: -8%;
        z-index: 0;
        width: 116%;
        height: 116%;
        object-fit: cover;
        object-position: center;
        filter: blur(26px) brightness(0.58) saturate(0.82);
        transform: scale(1.08);
        pointer-events: none;
      }

      .lk-opening-screen::before {
        content: "";
        position: absolute;
        inset: 0;
        z-index: 1;
        pointer-events: none;
        background: radial-gradient(
          circle at center,
          rgba(30, 18, 14, 0.04),
          rgba(0, 0, 0, 0.26) 82%
        );
      }

      .lk-opening-video {
        width: 100%;
        height: 100%;
        display: block;
        object-fit: cover;
        object-position: center;
        background: #000;
      }

      .lk-opening-stage::after {
        content: "";
        position: absolute;
        inset: auto 0 0;
        z-index: 2;
        height: 20%;
        pointer-events: none;
        background: linear-gradient(to top, rgba(0, 0, 0, 0.58), transparent);
      }

      .lk-op-sound-gate {
        position: absolute;
        left: 50%;
        top: 50%;
        z-index: 4;
