    if (chatId === null || chatId === undefined || chatId === '' || !Array.isArray(ctx.chat) || !ctx.chat.length) throw new Error('当前没有可建档的聊天。');
    const readMessages = helper('getChatMessages');
    const assistants = sync(readMessages(`0-${ctx.chat.length - 1}`, { role: 'assistant', include_swipes: true }), '读取楼层');
    const latest = assistants.at(-1);
    if (!latest) throw new Error('当前聊天没有助手楼层。');
    const id = messageId === undefined ? latest.message_id : messageId;
    if (!Number.isInteger(id) || id !== latest.message_id) throw new Error('该开局页已是历史楼层；请在当前分支最新助手楼层操作，不能覆盖旧状态。');
    const message = latest;
    if (!Number.isInteger(message.swipe_id) || message.swipe_id < 0 || !Array.isArray(message.swipes) || message.swipe_id >= message.swipes.length) throw new Error('未能识别当前 swipe，尚未写入。');
    const options = { type: 'message', message_id: id };
    const data = sync(mvu.getMvuData(options), '读取 MVU');
    if (!data?.stat_data) throw new Error('当前楼层没有 MVU 初始化数据，请先检查初始化通知。');
    return { H, mvu, ctx, chatId, characterId: ctx.characterId, groupId: ctx.groupId, chatRef: ctx.chat, messageId: id, messageRef: ctx.chat[id], swipeId: message.swipe_id,
      messageText: message.swipes?.[message.swipe_id], length: ctx.chat.length, data: cloneState(data), options };
  }
  function current(saved) {
    const now = position(saved.messageId);
    if (now.chatId !== saved.chatId || now.characterId !== saved.characterId || now.groupId !== saved.groupId ||
      now.chatRef !== saved.chatRef || now.messageRef !== saved.messageRef || now.length !== saved.length ||
      now.swipeId !== saved.swipeId || now.messageText !== saved.messageText) throw new Error('聊天、楼层或 swipe 已变化，请重新读取；草稿已保留。');
    return now;
  }
  function assertOpeningReplacement(saved) {
    const now = current(saved);
    // 只信实际宿主聊天：过滤后的助手列表无法证明中间没有用户消息。
    if (now.ctx.chat.length !== 1 || now.messageId !== 0) throw new Error('本局已经产生后续聊天，不能替换开局人物；请在新聊天使用该档案。');
    assertOpeningReplacementState(now.data.stat_data);
  }
  const api = createStateController({
    capture: async ({ messageId } = {}) => {
      // MVU 可能在本 iframe 创建后初始化；用本 iframe 的 Helper 安装动态 getter。
      // 等待仅放在读取入口，current/write 内的同步比较与更新不能插入 await。
      await helper('waitGlobalInitialized')('Mvu');
      return position(messageId);
    },
    current, assertOpeningReplacement,
    validate: value => {
      // 页面事务只验证，不借迁移或切章重算人际、补入人物默认字段。
      const parsed = createSchema(runtime().Z, { normalizeRelationships: false }).parse(value);
      const state = cloneState(value);
      // 仅规范已经存在的卷章别名，避免合法别名在终端目录中失配。
      state.场景.当前章 = parsed.场景.当前章;
      for (const name of Object.keys(state.场景.已发生事件)) state.场景.已发生事件[name].章段 = parsed.场景.已发生事件[name].章段;
      return state;
    },
    migrate: value => prepareStateMigration(value, runtime().Z),
    write: (saved, expected, state, { openingReplacement = false } = {}) => {
      if (openingReplacement) assertOpeningReplacement(saved);
      const now = current(saved), H = now.H;
      if (stateKey(now.data) !== stateKey(expected)) throw new Error('变量在提交前发生变化，请刷新。');
      // 使用宿主同步 updater：校验与赋值之间不 await，不退回 chat/global scope。
      const result = helper('updateVariablesWith')(variables => {
        current(saved);
        if (openingReplacement) assertOpeningReplacement(saved);
        if (stateKey(variables) !== stateKey(expected)) throw new Error('变量已经更新，未覆盖。');
        const next = cloneState(variables);
        next.stat_data = cloneState(state);
        // 页面事务提交的是已验证候选；缺项修复留给 MVU STARTED，避免暗改迁移候选。
        prepareRakudaiNativeMvu(next, [W, H], { repairStructure: false });
        return next;
      }, now.options);
      sync(result, '更新变量');
      return undefined;
    },
  });
  W.RakudaiStateController = api;
  // 开局页已有的照片入口只保存显示信息；沿用宿主聊天 scope，不进入 MVU。
  const displayTokens = new WeakMap();
  function displayStore(H) {
    return createPlayerDisplayStore({
      storage: {
        getItem: key => H.localStorage.getItem(key),
        setItem: (key, value) => H.localStorage.setItem(key, value),
      },
      getContext: () => H.SillyTavern.getContext(),
      onChange: value => {
        try { H.dispatchEvent(new H.CustomEvent('rk:player-portrait-changed', { detail: { scope: value.scope, revision: value.revision } })); } catch (_) {}
      },
    });
  }
  W.RakudaiPlayerDisplay = Object.freeze({
    capture() {
      const saved = position(), view = displayStore(saved.H).get(), token = Object.freeze({});
      displayTokens.set(token, { saved, view });
      return { ...view, token, primaryName: saved.data.stat_data.玩家?.姓名 || '' };
    },
    apply(expected, values) {
      const record = displayTokens.get(expected?.token);
      if (!record) throw new Error('头像操作已失效，请重新应用。');
      const now = current(record.saved), profileName = typeof values?.profileName === 'string' ? values.profileName.trim() : '';
      if (!profileName || now.data.stat_data.系统?.开局状态 !== '已建档' || now.data.stat_data.玩家?.姓名?.trim() !== profileName) {
        throw new Error('档案姓名与本局已建档玩家不一致，请载入本局人物的档案或照片。');
      }
      const oldName = record.view.profileName || record.saved.data.stat_data.玩家?.姓名 || '';
      return displayStore(now.H).save(record.view, { avatarUrl: values.avatarUrl,
        aliases: oldName && oldName !== profileName ? [] : record.view.aliases, profileName, source: 'opening' });
    },
  });
})();

})();
</script>
<!-- RK_STATE_CONTROLLER_END -->
<script>
      (function () {
        var root = document.getElementById("lkPrelude");
        var openingScreen = document.getElementById("lkOpeningScreen");
        var titleScreen = document.getElementById("lkTitleScreen");
        var video = document.getElementById("lkOpeningVideo");
        var videoBackdrop = document.getElementById("lkOpeningVideoBackdrop");
        var soundGate = document.getElementById("lkOpSoundGate");
        var skipButton = document.getElementById("lkOpSkip");
        var continuePrompt = document.getElementById("lkContinuePrompt");
        var titleVisible = false;
        var needsGesture = false;
        var finished = false;
        var messageHost = root.closest(".mes_text, .mes_block");
        var localParent = root.parentElement || document.body;

        window.__lkPreludeComplete = false;

        if (messageHost) {
          root.classList.add("is-message-embedded");
          messageHost.classList.add("lk-prelude-host-active");
          document.body.classList.remove("prelude-active");
        }

        function setGuideInert(inert) {
          Array.prototype.forEach.call(localParent.children, function (child) {
            if (
              child !== root &&
              child.tagName !== "SCRIPT" &&
              child.tagName !== "STYLE"
            ) {
              child.inert = inert;
            }
          });
        }

        function showSoundGate() {
          needsGesture = true;
          videoBackdrop.pause();
          soundGate.classList.add("is-visible");
        }

        function syncOpeningBackdrop(force) {
          try {
            if (
              force ||
              Math.abs(videoBackdrop.currentTime - video.currentTime) > 0.45
            ) {
              videoBackdrop.currentTime = video.currentTime;
            }
          } catch (error) {
            /* 元数据尚未就绪时，playing 事件会再次同步。 */
          }
        }

        function playOpeningBackdrop() {
          syncOpeningBackdrop(true);
          videoBackdrop.muted = true;
          var backdropPromise = videoBackdrop.play();
          if (backdropPromise && typeof backdropPromise.catch === "function") {
            backdropPromise.catch(function () {});
          }
        }

        function markOpeningPlaying() {
          needsGesture = false;
          soundGate.classList.remove("is-visible");
          playOpeningBackdrop();
        }

        function playOpeningWithSound() {
          video.defaultMuted = false;
          video.muted = false;
          video.volume = 1;
          var playPromise = video.play();
          if (playPromise && typeof playPromise.then === "function") {
            playPromise.then(markOpeningPlaying).catch(showSoundGate);
          }
        }

        function revealTitle() {
          if (titleVisible || finished) return;
          titleVisible = true;
          video.pause();
          videoBackdrop.pause();
          openingScreen.classList.remove("is-active");
          openingScreen.setAttribute("aria-hidden", "true");
          titleScreen.classList.add("is-active");
          titleScreen.setAttribute("aria-hidden", "false");
          document.dispatchEvent(new CustomEvent("lk:title-visible"));
          continuePrompt.focus({ preventScroll: true });
        }

        function finishPrelude() {
          if (!titleVisible || finished) return;
          finished = true;
          window.__lkPreludeComplete = true;
          document.body.classList.remove("prelude-active");
          setGuideInert(false);
          root.classList.add("is-finished");
          document.dispatchEvent(new CustomEvent("lk:prelude-complete"));

          document.removeEventListener("keydown", handlePreludeKey, true);
          window.setTimeout(function () {
            root.hidden = true;
            if (messageHost) {
              messageHost.classList.remove("lk-prelude-host-active");
            }
          }, 450);
        }

        function handleOpeningClick(event) {
          if (event.target === soundGate || event.target === skipButton) return;
          if (needsGesture || video.paused) {
            playOpeningWithSound();
          } else {
            revealTitle();
          }
        }

        function handlePreludeKey(event) {
          if (finished || event.repeat) return;
          event.preventDefault();
          event.stopImmediatePropagation();
          if (!titleVisible) {
            if (needsGesture || video.paused) {
              playOpeningWithSound();
            } else {
              revealTitle();
            }
            return;
          }
          finishPrelude();
        }

        soundGate.addEventListener("click", function (event) {
          event.stopPropagation();
          playOpeningWithSound();
        });
        skipButton.addEventListener("click", function (event) {
          event.stopPropagation();
          revealTitle();
        });
        openingScreen.addEventListener("click", handleOpeningClick);
        titleScreen.addEventListener("click", finishPrelude);
        video.addEventListener("playing", markOpeningPlaying);
        video.addEventListener("timeupdate", function () {
          syncOpeningBackdrop(false);
        });
        video.addEventListener("seeking", function () {
          syncOpeningBackdrop(true);
        });
        video.addEventListener("ended", revealTitle, { once: true });
        video.addEventListener("error", revealTitle, { once: true });
        videoBackdrop.addEventListener(
          "error",
          function () {
            videoBackdrop.hidden = true;
          },
          { once: true },
        );
        document.addEventListener("keydown", handlePreludeKey, true);
        function activatePreludeScope() {
          setGuideInert(true);
        }

        if (document.readyState === "loading") {
          document.addEventListener("DOMContentLoaded", activatePreludeScope, {
            once: true,
          });
        } else {
          activatePreludeScope();
        }

        if (document.readyState === "complete") {
          playOpeningWithSound();
        } else {
          window.addEventListener("load", playOpeningWithSound, { once: true });
        }
      })();
    </script>

